int N;
vector<string> strs;

set<int> non_zero;
int mapped_num[26];
bool used[10];
int max_len;


int dfs(int x, int y, int s){
    if(x >= max_len){
        if(s == 0) return 1;
        else return 0;
    }
    if(y == N - 1){
        if(x >= strs[y].size()) return 0;
        int d = strs[y][strs[y].size()-1-x] - 'A';
        if(mapped_num[d] == -1){
            int i = s % 10;
            if(used[i]) return 0;
            if(i == 0 && non_zero.count(d) > 0) return 0;
            used[i] = true;
            mapped_num[d] = i;
            int ret = dfs(x+1, 0, s / 10);
            mapped_num[d] = -1;
            used[i] = false;
            return ret;
        }else{
            if(mapped_num[d] != s % 10) return 0;
            return dfs(x+1, 0, s / 10);
        }
    }else{
        if(x >= strs[y].size()) return dfs(x, y+1, s);
        int d = strs[y][strs[y].size()-1-x] - 'A';
        if(mapped_num[d] != -1) return dfs(x, y+1, s+mapped_num[d]);
        int ret = 0;
        for(int i=0;i<10;i++){
            if(used[i]) continue;
            if(i == 0 && non_zero.count(d) > 0) continue;
            used[i] = true;
            mapped_num[d] = i;
            ret += dfs(x, y+1, s+i);
            mapped_num[d] = -1;
            used[i] = false;
        }
        return ret;
    }
}


