using namespace std;
int dp[1 << 20][20], a[20], r[20][20];
int n, m, k;
int sol(int mask, int cnt, int last) {
  if (cnt == m) return 0;
  if (dp[mask][last] != -1) return dp[mask][last];
  int res = 0;
  for (int i = 0; i < n; i++) {
    if ((mask & (1 << i)) != 0) continue;
    res = max(res, sol(mask | (1 << i), cnt + 1, i) + a[i] + r[last][i]);
  }
  return dp[mask][last] = res;
}
int main() {
  cin >> n >> m >> k;
  for (int i = 0; i < n; i++) cin >> a[i];
  for (int j = 0; j < k; j++) {
    int x, y, c;
    cin >> x >> y >> c;
    x--, y--;
    r[x][y] = c;
  }
  memset(dp, -1, sizeof dp);
  cout << sol(0, 0, 0) << '\n';
  return 0;
}

