def solve(strip, n):
    if n == 1:
        return strip.get(0, 0) in (0, 3)
    strip[n] = 3
    keys = sorted(strip)
    dp_prev = [0] * 4
    dp_prev[strip.get(0, 0)] = 1
    i = 1
    pos = 0
    while i <= n:
        if i not in strip:
            while pos < len(keys) and keys[pos] < i:
                pos += 1
            j = keys[pos]
            i = max(i, i + (j - i - 2) // 2 * 2)
        red = strip.get(i, 0)

        dp = [0] * 4
        if dp_prev[0] or dp_prev[3]:
            dp[red] = 1
        if dp_prev[1]:
            if (red & 2) == 0:
                dp[red | 2] = 1
        if dp_prev[2]:
            if (red & 1) == 0:
                dp[red | 1] = 1
        dp_prev = dp
        i += 1

    return dp_prev[3]

