int main() {
  int N;
  cin >> N;
  int A[N];
  for (int i = 0; i < N; i++) cin >> A[i];
  vector<int> H(N + 1, 0), T(N + 1, 1);
  for (int i = 0; i < N; i++) H[A[i]]++;
  int j = 1;
  int Ans = 0;
  for (int i = 0; i < N; i++) {
    if (H[A[i]] != 1) {
      while (j <= N) {
        if (H[j] == 0) {
          break;
        }
        j++;
      }
      if (j > N) break;
      if (j < A[i] || T[A[i]] == 0) {
        H[A[i]]--;
        A[i] = j;
        H[j] = 1;
        Ans++;
      } else
        T[A[i]]--;
    }
  }
  cout << Ans << endl;
  for (int i = 0; i < N; i++) cout << A[i] << " ";
}

def is_lucky(number_to_check):
    digits = []
    if number_to_check < 10:
        digits.append(number_to_check)
    else:
        while number_to_check / 10 > 0:
            digit = number_to_check % 10
            digits.insert(0, digit)
            number_to_check = int(number_to_check / 10)

    is_four = False
    is_seven = False
    count = 0
    for digit in digits:
        if digit == 4:
            if len(digits) == 1:
                return True
            else:
                is_four = True
                count += 1
                continue
        elif digit == 7:
            if len(digits) == 1:
                return True
            else:
                is_seven = True
                count += 1
                continue
        else:
            return False
    return is_four and is_seven and count == len(digits)


