	int vNum;
	int qNum;

	Tree tree;
	int[] deg;

	RSQ potencial;
	RSQ[] rsqs;

	int rootSum = 0;

	int[] branch;
	int[] index;
	int[] size;

	void solve() throws IOException  {

		vNum = nextInt();
		qNum = nextInt();

		tree = new Tree(vNum);
		deg = new int [vNum];

		for (int i = 1; i < vNum; i++) {
			int u = nextInt() - 1;
			int v = nextInt() - 1;
			tree.add(u, v);
			tree.add(v, u);
			deg[u]++;
			deg[v]++;
		}

		rsqs = new RSQ [deg[0]];
		potencial = new RSQ(0, vNum);
		size = new int [deg[0]];
		branch = new int [vNum];
		index = new int [vNum];

		for (int branch = 0, idx = tree.head[0]; idx != 0; idx = tree.next[idx]) {
			int nv = tree.vert[idx];
			size[branch] = buildBranch(branch, nv, 0, 0);
			rsqs[branch] = new RSQ(0, size[branch] - 1);
			branch++;
		}

		for (int q = 0; q < qNum; q++) {

			int qt = nextInt();
			int v = nextInt() - 1;

			if (qt == 0) {

				int x = nextInt();
				int d = nextInt();

				if (v == 0) {
					increaseBranches(d, x, -1);
					rootSum += x;
				} else {
					int pos = index[v];

					int l = max(0, pos - d);
					int r = min(size[branch[v]] - 1, pos + d);
					rsqs[branch[v]].add(l, r, x);

					if (pos < d) {
						increaseBranches(d - pos - 1, x, branch[v]);
						rootSum += x;
					}

				}

			} else {

				if (v == 0) {
					out.println(rootSum);
				} else {
					int pos = index[v];
					out.println(rsqs[branch[v]].sum(pos, pos) + potencial.sum(pos, pos));
				}

			}
		}

	}

	void increaseBranches(int d, int x, int exception) {

		int l = 0;
		int rr = d - 1;

		if (l <= rr) {
			int r = min(rr, vNum - 1);
			potencial.add(l, r, x);

			if (exception != -1) {
				rsqs[exception].add(l, min(r, size[exception] - 1), -x);
			}
		}

	}

	int buildBranch(int branchIdx, int v, int p, int pos) {

		branch[v] = branchIdx;
		index[v] = pos;

		int size = 1;

		for (int idx = tree.head[v]; idx != 0; idx = tree.next[idx]) {

			int nv = tree.vert[idx];
			if (nv == p) continue;
			size += buildBranch(branchIdx, nv, v, pos + 1);
		}

		return size;
	}

	class Tree {
		int vNum;
		int[] head;
		int[] next;
		int[] vert;
		int cnt = 1;

		Tree(int vNum) {
			head = new int [vNum];
			next = new int [2 * vNum - 1];
			vert = new int [2 * vNum - 1];
		}

		void add(int u, int v) {
			next[cnt] = head[u];
			vert[cnt] = v;
			head[u] = cnt++;
		}
	}

	class RSQ {
		int NEYTRAL = 0, size = 1;
		int[] val, pot, left, right;

		RSQ(int l, int r) {
			for (int ln = (r - l + 1); size < ln; size <<= 1);
			val = new int [2 * size];
			pot = new int [2 * size];
			left = new int [2 * size];
			right = new int [2 * size];
			build(1, l, r);
		}

		void build(int v, int l, int r) {
			left[v] = l; right[v] = r;
			if (l != r) {
				build(v << 1, l, (l + r) >> 1);
				build((v << 1) + 1, ((l + r) >> 1) + 1, r);
			}
		}

		void add(int l, int r, int v) {
			add(1, l, r, v);
		}

		int add(int v, int l, int r, int x) {
			if (l <= left[v] && right[v] <= r)
				pot[v] += x;
			else if (l <= right[v] && left[v] <= r)
				val[v] = add(v << 1, l, r, x) + add((v << 1) + 1, l, r, x);
			return val(v);
		}

		int sum(int l, int r) {
			return sum(1, l, r);
		}

		int sum(int v, int l, int r) {
			if (l <= left[v] && right[v] <= r)
				return val(v);
			if (l <= right[v] && left[v] <= r)
				return sum(v << 1, l, r) + sum((v << 1) + 1, l, r) + pot[v] * (min(r, right[v]) - max(l, left[v]) + 1);
			return NEYTRAL;
		}

		int val(int v) {
			return val[v] + pot[v] * (right[v] - left[v] + 1);
		}
	}

