int main() {
  char wall[9][6] = {'\0'};
  char state = 'R';
  for (int i = 0; i < 9; ++i) {
    cin >> wall[i];
    if (cin.eof()) break;
  }
  int r = 0, c = 0;
  cout << 'R';
  while (1) {
    static char state = 'R';
    switch (state) {
      case 'R':
        if (r != 0 && wall[r - 1][c + 1] == '1') {
          cout << 'U';
          state = 'U';
          ++c;
          --r;
        } else if (c != 3 && wall[r][c + 1] == '1') {
          cout << 'R';
          ++c;
        } else if (r != 8 && wall[r + 1][c + 1] == '1') {
          cout << 'D';
          state = 'D';
          ++r;
          ++c;
        } else {
          cout << endl;
          return 0;
        }
        break;
      case 'D':
        if (c != 5 && wall[r + 1][c] == '1') {
          cout << 'R';
          state = 'R';
          ++r;
        } else if (r != 7 && wall[r + 2][c] == '1') {
          cout << 'D';
          r += 2;
        } else if (c != 0 && wall[r + 1][c - 1] == '1') {
          cout << 'L';
          state = 'L';
          --c;
          ++r;
        } else {
          cout << endl;
          return 0;
        }
        break;
      case 'L':
        if (r != 8 && wall[r + 1][c] == '1') {
          cout << 'D';
          state = 'D';
          ++r;
        } else if (c != 0 && wall[r][c - 1] == '1') {
          cout << 'L';
          --c;
        } else if (r != 0 && wall[r - 1][c] == '1') {
          cout << 'U';
          state = 'U';
          --r;
        } else {
          cout << endl;
          return 0;
        }
        break;
      case 'U':
        if (c != 0 && wall[r - 1][c - 1] == '1') {
          cout << 'L';
          state = 'L';
          --r;
          --c;
        } else if (r != 1 && wall[r - 2][c] == '1') {
          cout << 'U';
          r -= 2;
        } else if (c != 4 && wall[r - 1][c] == '1') {
          cout << 'R';
          state = 'R';
          --r;
        } else {
          cout << endl;
          return 0;
        }
        break;
      default:
        cout << " error " << endl;
        return -1;
    }
  }
}

