inline void add(int l, int r, int t, int ql, int qr, int c) {
  if (l == ql && r == qr) {
    f[t] += (r - l + 1) * c, tg[t] += c;
    return;
  }
  f[t] += (qr - ql + 1) * c;
  int d = (l + r) >> 1;
  if (ql <= d) add(l, d, t << 1, ql, min(d, qr), c);
  if (d + 1 <= qr) add(d + 1, r, t << 1 | 1, max(d + 1, ql), qr, c);
}
inline void getans(int l, int r, int t, int ql, int qr) {
  if (l == ql && r == qr) {
    sum += f[t];
    return;
  }
  int d = (l + r) >> 1;
  f[t << 1] += 1ll * (d - l + 1) * tg[t];
  f[t << 1 | 1] += 1ll * (r - d) * tg[t];
  tg[t << 1] += tg[t], tg[t << 1 | 1] += tg[t], tg[t] = 0;
  if (ql <= d) getans(l, d, t << 1, ql, min(d, qr));
  if (d + 1 <= qr) getans(d + 1, r, t << 1 | 1, max(d + 1, ql), qr);
}
